require_once __DIR__.'/../includes/bootstrap.php';$user=current_user();$stmt=db()->query("SELECT o.id,o.name,o.organization_type,o.address,o.phone,COUNT(DISTINCT d.id) AS department_count FROM organizations o LEFT JOIN departments d ON d.organization_id=o.id AND d.status='active' WHERE o.approval_status='approved' GROUP BY o.id ORDER BY o.name");$providers=$stmt->fetchAll();$external=[];try{$external=db()->query('SELECT * FROM public_provider_directory ORDER BY location_label,name')->fetchAll();}catch(Throwable $e){error_log('Provider directory migration has not been applied.');}$pageTitle='Find healthcare providers';require __DIR__.'/../includes/header.php';?>
<section class="page-intro"><span class="eyebrow">FIND CARE</span><h1>Healthcare providers <span>you can look up.</span></h1><p>CareBridge-listed organizations can receive appointment requests inside this platform. Public directory entries are real Nepal institutions listed with official contact details; their booking and records are not connected to CareBridge unless they register and are approved.</p></section>
<section class="section-block"><div class="section-heading section-heading-left"><span class="eyebrow">CAREBRIDGE NETWORK</span><h2>Approved CareBridge providers</h2></div><div class="provider-grid"><?php if(!$providers):?><div class="empty-state"><h3>No enrolled providers yet</h3><p>Use the public directory below to contact an institution, or check back as more providers join CareBridge.</p></div><?php else:foreach($providers as $p):?><article class="provider-card"><span class="status status-success">CareBridge approved</span><h3><?=e($p['name'])?></h3><p><?=e(ucwords(str_replace('_',' ',$p['organization_type'])))?></p><p><?=e($p['address'])?></p><p><?=e($p['phone']?:'Contact provider for details')?></p><small><?= (int)$p['department_count']?> departments available</small><a class="button button-full" href="<?=e(url('appointments/book.php?organization_id='.(int)$p['id']))?>">Book appointment →</a></article><?php endforeach;endif;?></div></section>
<section class="section-block"><div class="section-heading section-heading-left"><span class="eyebrow">PUBLIC DIRECTORY · NEPAL</span><h2>Real hospitals & service centres</h2><p>Details below are taken from the institutions' official websites. Verify current services, hours, and contact details directly with the institution.</p></div><div class="provider-grid"><?php foreach($external as $p):?><article class="provider-card external-provider"><span class="status">Official public listing</span><h3><?=e($p['name'])?></h3><p><strong><?=e($p['location_label'])?></strong> · <?=e($p['organization_type'])?></p><p><?=e($p['address'])?></p><p><?=e($p['phone'])?></p><?php if($p['email']):?><p><?=e($p['email'])?></p><?php endif;?><a class="text-link" href="<?=e($p['official_url'])?>" target="_blank" rel="noopener noreferrer">Official website ↗</a><p class="source-note">Source: <a href="<?=e($p['source_url'])?>" target="_blank" rel="noopener noreferrer">Official contact page</a></p></article><?php endforeach;?></div></section>
